  "inlineSchema": "// This is your Prisma schema file\n// Learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  MEMBER\n  MODERATOR\n  ADMIN\n}\n\nenum CaseStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum CaseSeverity {\n  CRITICAL // Changements majeurs avec fort impact\n  WARNING // Changements significatifs à surveiller\n  STABLE // Alternatives stables et fiables\n}\n\nenum NotificationType {\n  REPLY // Quelqu'un répond à votre post/commentaire\n  MENTION // Quelqu'un vous mentionne @username\n  UPVOTE // Votre post/commentaire reçoit un upvote\n  REACTION // Quelqu'un réagit à votre post\n  BADGE_UNLOCKED // Vous débloquez un nouveau badge\n  CASE_APPROVED // Votre cas signalé est approuvé\n  CASE_REJECTED // Votre cas signalé est rejeté\n  CASE_UPDATED // Un cas que vous avez signalé est mis à jour\n  POST_PINNED // Votre post a été épinglé\n}\n\nmodel User {\n  id           String  @id @default(cuid())\n  email        String  @unique\n  name         String\n  password     String\n  role         Role    @default(MEMBER)\n  organization String?\n\n  // Gamification\n  reputation Int    @default(0) // Points de réputation\n  badges     String @default(\"\") // JSON string containing array of badges\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  cases         Case[]\n  posts         Post[]\n  comments      Comment[]\n  postVotes     PostVote[]\n  commentVotes  CommentVote[]\n  reactions     PostReaction[]\n  notifications Notification[]\n\n  @@map(\"users\")\n}\n\nmodel Case {\n  id                String       @id @default(cuid())\n  companyName       String\n  productName       String\n  category          String\n  licenseInitial    String\n  licenseFinal      String\n  changeDate        String\n  website           String\n  description       String\n  legalAnalysis     String\n  communityReaction String\n  sources           String // JSON string containing array of sources\n  alternatives      String? // JSON string containing array of alternatives\n  status            CaseStatus   @default(PENDING)\n  severity          CaseSeverity @default(WARNING) // Niveau de gravité du changement\n  reportCount       Int          @default(1) // Nombre de fois que le cas a été signalé\n\n  // Reporter info\n  reporterId String\n  reporter   User   @relation(fields: [reporterId], references: [id])\n\n  // Metadata\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"cases\")\n}\n\n// Forum Models\nmodel Post {\n  id       String @id @default(cuid())\n  title    String\n  content  String // Markdown content\n  category String\n  tags     String @default(\"\") // JSON array of tags\n\n  // Author\n  authorId String\n  author   User   @relation(fields: [authorId], references: [id])\n\n  // Moderation\n  isPinned Boolean @default(false)\n\n  // Engagement\n  views     Int @default(0)\n  upvotes   Int @default(0)\n  downvotes Int @default(0)\n\n  // Relations\n  comments  Comment[]\n  votes     PostVote[]\n  reactions PostReaction[]\n\n  // Metadata\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"posts\")\n}\n\nmodel Comment {\n  id      String @id @default(cuid())\n  content String\n\n  // Author\n  authorId String\n  author   User   @relation(fields: [authorId], references: [id])\n\n  // Post relation\n  postId String\n  post   Post   @relation(fields: [postId], references: [id], onDelete: Cascade)\n\n  // Parent comment (for nested replies)\n  parentId String?\n  parent   Comment?  @relation(\"CommentReplies\", fields: [parentId], references: [id], onDelete: Cascade)\n  replies  Comment[] @relation(\"CommentReplies\")\n\n  // Engagement\n  upvotes   Int @default(0)\n  downvotes Int @default(0)\n\n  // Relations\n  votes CommentVote[]\n\n  // Metadata\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"comments\")\n}\n\nmodel PostVote {\n  id    String @id @default(cuid())\n  value Int // 1 for upvote, -1 for downvote\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  postId String\n  post   Post   @relation(fields: [postId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([userId, postId])\n  @@map(\"post_votes\")\n}\n\nmodel CommentVote {\n  id    String @id @default(cuid())\n  value Int // 1 for upvote, -1 for downvote\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  commentId String\n  comment   Comment @relation(fields: [commentId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([userId, commentId])\n  @@map(\"comment_votes\")\n}\n\n// Emoji reactions on posts\nmodel PostReaction {\n  id    String @id @default(cuid())\n  emoji String // 👍 👎 🔥 ❤️ 😂 😮 😢 😡\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  postId String\n  post   Post   @relation(fields: [postId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([userId, postId, emoji])\n  @@map(\"post_reactions\")\n}\n\n// Notifications system\nmodel Notification {\n  id      String           @id @default(cuid())\n  type    NotificationType\n  title   String\n  message String\n  link    String? // URL vers la ressource concernée\n  isRead  Boolean          @default(false)\n\n  // Metadata optionnelle (JSON pour flexibilité)\n  metadata String? // JSON: {postId, commentId, authorName, etc.}\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, isRead])\n  @@index([userId, createdAt])\n  @@map(\"notifications\")\n}\n",
